import { useState } from 'react';
import { MessageSquare, Check, Loader2, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { openerReallySent } from '@/lib/leadState';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { WHATSAPP_TEMPLATES, type OutreachLead } from '@/types/outreach';
import { TemplatePreviewButton, TemplateSnippet } from '@/components/TemplateWordingPreview';
import { RequestTemplateButton } from '@/components/RequestTemplateButton';
import { classifyLineType } from '@/lib/lineType';
import { coldWhatsAppVerdict, COLD_NOT_ELIGIBLE_LABEL } from '@/lib/coldWhatsAppEligibility';
import { templateDestinationRefusal } from '@/lib/whatsAppDestination';
import { toWhatsAppDigits } from '@/lib/waNumber';
import { COUNTRY_OFF, marketsOn } from '@/lib/outreachMarkets';
import { useCountrySettings } from '@/hooks/useCountrySettings';
import { isInitialOpener } from '@/lib/openerVariant';
import { queueDropWords, REPORT_OFFER_TEMPLATE } from '@/lib/reportOfferTemplate';
import { checkReportOffer } from '@/lib/reportOfferCheck';
import { useAuth } from '@/hooks/useAuth';
import { getTemplateSendability } from '@/lib/whatsappTemplates';
import { useLeadPermissions } from '@/hooks/useLeadPermissions';
import { salesQueueOpener } from '@/lib/leadRpc';
import { CALL_CAMPAIGN_EXPLAINER, callCampaignLeads, callCampaignQuestion } from '@/lib/callCampaignGuard';
import { QUEUE_SKIP_LABEL, refusalText } from '@/lib/salesCrm';
import { isColdOutreachTemplate } from '@/lib/coldOutreach';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { useQueueState } from '@/hooks/useQueueState';
import { fetchQueueState, queuedLeadLine } from '@/lib/queueStatus';
import { WorkSection } from '@/components/WorkSection';
import { notifyLeadChanged } from '@/lib/leadSync';
import { announceQueueChanged } from '@/lib/whatsappQueueView';

/**
 * Per-lead WhatsApp outreach controls (lead detail dialog): pick the approved
 * template for THIS business, then add/remove it from the daily outreach queue.
 * Sending itself is done server-side by process-whatsapp-queue (TEST_MODE-gated);
 * here we only choose the template + queue the lead (status='queued').
 */
export function WhatsAppLeadControls({
  lead,
  onUpdate,
}: {
  lead: OutreachLead;
  onUpdate: (leadId: string, data: Partial<OutreachLead>) => Promise<unknown> | void;
}) {
  const [busy, setBusy] = useState(false);
  const { toast } = useToast();
  const { user } = useAuth();
  /* The report offer is checked before it is queued (2026-10-14): a reason, never a failed send later. Fails closed. */
  const reportOfferBlocked = async (): Promise<boolean> => {
    if (template !== REPORT_OFFER_TEMPLATE) return false;
    const c = await checkReportOffer([lead.id]);
    const r = c.ok ? c.results[lead.id] : null;
    if (!r) { toast({ title: 'Not queued', description: 'Could not check this lead for the report offer, so nothing was queued.', variant: 'destructive' }); return true; }
    if (!r.ok) { toast({ title: 'Not queued', description: `Report offer: ${r.reason ?? 'not sendable'}.`, variant: 'destructive' }); return true; }
    if (r.warnings.length) toast({ title: 'Check before it sends', description: `This lead is ${r.warnings.join(' and ')}.` });
    return false;
  };
  const { settings: countrySettings } = useCountrySettings();
  /* ⛔ SAME CONTROL, BOTH ROLES (2026-09-27). The admin stores the template on the lead and queues it
     directly, as before. A salesperson cannot write the lead row: they choose the opener here and
     sales_queue_opener stores THAT template and queues it, with the same never-contacted, UK-mobile,
     opt-out and ownership checks — or says why it did not. */
  const perms = useLeadPermissions();
  const salesPath = !perms.queueControls;
  const [salesTemplate, setSalesTemplate] = useState('');
  const template = salesPath ? salesTemplate : (lead.whatsapp_template ?? '');
  const queued = lead.status === 'queued';
  /* ⛔ THE QUEUED LINE SAYS WHETHER THE QUEUE IS ACTUALLY SENDING (2026-09-28): paused by the admin
     outranks the sending window, and an unreadable state never claims it will send. */
  const queueLine = queuedLeadLine(useQueueState(queued), lead.phone);
  /* A salesperson's single-lead queue is the bulk opener path, so it offers the approved openers. */
  const options = salesPath ? WHATSAPP_TEMPLATES.filter((t) => isInitialOpener(t.value) || t.value === REPORT_OFFER_TEMPLATE) : WHATSAPP_TEMPLATES;
  /* A template must be CHOSEN before this lead can be queued. Only a name that is currently in the
     allowlist counts: a lead can be carrying a value from a removed or renamed template, and
     inheriting that silently is the same problem as substituting one. Removing from the queue is
     always allowed — being unable to cancel because of a bad template would be worse. */
  /* Both openers are ordinary choices (src/lib/openerVariant.ts): only Meta approval can refuse one. */
  const approval = template ? getTemplateSendability(template, { shareToken: null }, {}) : { ok: true as const };
  const templateChosen = !!template && options.some((t) => t.value === template) && approval.ok;

  /* ⛔ A lead in a Call campaign gets WhatsApp only when the person says so (2026-10-15). Fails closed. Null = do not queue. */
  const callCampaignAnswer = async (): Promise<boolean | null> => {
    const cc = await callCampaignLeads(supabase, [lead]);
    if (!cc.ok) { toast({ title: 'Not queued', description: 'Could not check which campaign this lead is in, so nothing was queued.', variant: 'destructive' }); return null; }
    if (cc.leads.length === 0) return false;
    return window.confirm(`${callCampaignQuestion(1)} ${CALL_CAMPAIGN_EXPLAINER}`) ? true : null;
  };

  const salesQueue = async () => {
    if (!templateChosen) return;
    setBusy(true);
    try {
      if (await reportOfferBlocked()) return;
      const callOk = await callCampaignAnswer();
      if (callOk === null) return;
      const r = await salesQueueOpener([lead.id], template, callOk);
      if (!r.ok) { toast({ title: 'Not queued', description: refusalText(r.error), variant: 'destructive' }); return; }
      const skipped = Object.keys((r.skipped ?? {}) as Record<string, number>);
      if (!r.queued) {
        toast({ title: 'Not queued', description: skipped.map((k) => QUEUE_SKIP_LABEL[k] ?? k).join(', ') || 'Refused', variant: 'destructive' });
        return;
      }
      const st = await fetchQueueState().catch(() => null);
      toast({ title: 'Queued for WhatsApp', description: `${template} — ${queuedLeadLine(st, lead.phone).text} The queue re-checks it before it sends.` });
      notifyLeadChanged(lead.id); // every screen AND other tabs (the hand-fired event reached this tab only)
      announceQueueChanged();
    } finally { setBusy(false); }
  };

  const toggleQueue = async () => {
    // Guard as well as the disabled button: the button can be bypassed by a stale render, and this
    // write is the thing that decides what a real business receives.
    if (!queued && !templateChosen) return;
    setBusy(true);
    try {
      if (queued) {
        // Restore the status the lead had BEFORE queueing (fallback not_contacted).
        await onUpdate(lead.id, {
          status: lead.previous_status ?? 'not_contacted',
          previous_status: null,
          queued_at: null,
          contact_method: null, // clear the WhatsApp tag set at queue-time
        });
      } else {
        // Tier-1 offline line-type gate: only mobiles may be queued. A non-mobile
        // (landline/VoIP/etc.) is flagged 'no_whatsapp_needs_sms' instead of queued — the
        // status name is historical; it is the landline marker, and no send is ever attempted.
        /* ⛔ THE REAL-CONTACT GUARD (2026-10-05): a COLD template is not queued for a lead with a genuine logged
           conversation — the ONE shared rule (SQL opener_contact_block, via contact_check), the same answer a
           campaign launch and the sales queue get; the drip refuses it again at send time. Fails closed. */
        if (isColdOutreachTemplate(template)) {
          const { data: chk, error: chkErr } = await supabase.functions.invoke('process-whatsapp-queue', { body: { mode: 'contact_check', phones: [], lead_ids: [lead.id] } });
          const res = chk as { ok?: boolean; conversation?: Record<string, string> } | null;
          if (chkErr || !res?.ok) { toast({ title: 'Not queued', description: 'Could not check the contact history, so nothing was queued.', variant: 'destructive' }); return; }
          const block = res.conversation?.[lead.id];
          if (block) { toast({ title: 'Not queued', description: (QUEUE_SKIP_LABEL[block] ?? QUEUE_SKIP_LABEL.contacted_by_phone).replace(/^./, (c) => c.toUpperCase()) + '.', variant: 'destructive' }); return; }
        }
        /* 2026-10-14: a Malaysia / Singapore mobile while WhatsApp to that country is switched off is not queued — and is
           never flagged No mobile (it is a mobile). src/lib/outreachMarkets.ts. */
        if (isColdOutreachTemplate(template)) {
          const v = coldWhatsAppVerdict(lead.phone, lead.country, marketsOn(countrySettings, 'whatsapp'));
          if (v.eligible === false && v.reason === COUNTRY_OFF) {
            toast({ title: 'Not queued', description: 'WhatsApp to this country is switched off. Paul can turn it on in the WhatsApp queue settings.', variant: 'destructive' });
            return;
          }
          /* ⛔ 2026-10-19: the WHOLE cold verdict, as the bulk queue and the drip use it — no phone, an unusable number
             or a non-mobile is flagged No mobile and NOT queued, and the person is told (it used to be silent, and a
             no-phone lead was queued). */
          if (v.eligible === false) {
            await onUpdate(lead.id, { status: 'no_whatsapp_needs_sms', line_type: classifyLineType(lead.phone, lead.country).lineType, line_type_checked_at: new Date().toISOString() });
            toast({ title: 'Not queued', description: `Skipped: ${COLD_NOT_ELIGIBLE_LABEL[v.reason]}. Not sendable on WhatsApp.`, variant: 'destructive' });
            return;
          }
        }
        if (await reportOfferBlocked()) return;
        if (await callCampaignAnswer() === null) return;
        const { lineType, whatsappEligible } = classifyLineType(lead.phone, lead.country);
        const knownNonMobile = templateDestinationRefusal(toWhatsAppDigits(lead.phone, lead.country)) !== null;
        if (!whatsappEligible || knownNonMobile) {
          await onUpdate(lead.id, {
            status: 'no_whatsapp_needs_sms',
            line_type: whatsappEligible ? (lead.phone ? 'landline' : lineType) : lineType,
            line_type_checked_at: new Date().toISOString(),
          });
          toast({ title: 'Not queued', description: lead.phone ? 'Skipped: landline, not sendable on WhatsApp.' : 'Skipped: no phone number, not sendable on WhatsApp.', variant: 'destructive' });
          return;
        }
        await onUpdate(lead.id, {
          status: 'queued',
          previous_status: lead.status, // capture pre-queue status for restore-on-cancel
          queued_at: new Date().toISOString(),
          // The operator's OWN choice, never a substitute. This was
          //   whatsapp_template: template || 'booking_page_intro'
          // so queueing without touching the picker wrote a barber booking-page pitch onto the
          // lead, and the queue would later send it. The picker shows "Choose a template" in that
          // state, so nothing on screen said a template had been decided — the value appeared out
          // of nowhere and looked chosen. The button is now disabled until one is picked, and this
          // write is unreachable without it.
          whatsapp_template: template,
          queued_by_user_id: user?.id ?? null, // the report offer is signed with THIS person's own name
          whatsapp_attempts: 0, // fresh retries (e.g. re-queuing a whatsapp_failed lead)
          line_type: lineType, // cache the offline result
          contact_method: 'whatsapp', // attribute to WhatsApp immediately
        });
      }
    } finally {
      setBusy(false);
      /* The one queue (both roles) re-reads now, not at its next poll. */
      announceQueueChanged();
    }
  };

  /* ⛔ FOLDED TO ITS STATE (declutter pass 2, 2026-10-01). The three settled states (not on WhatsApp, a
     landline, the opener already sent) are one line with nothing to open. Otherwise the line says where the
     queue stands; the template picker and the queue button are inside. A failed send and a PAUSED queue are
     warnings — drawn while folded. */
  const sentDay = lead.whatsapp_sent_at ? new Date(lead.whatsapp_sent_at).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'Europe/London' }) : '';
  if (lead.status === 'no_whatsapp') {
    return <WorkSection icon={MessageSquare} iconClass="text-green-500" title="WhatsApp outreach" testId="whatsapp-outreach" summaryClass="text-amber-600 dark:text-amber-400"
      summary="No WhatsApp — this mobile can't receive it. A text or a call still works." />;
  }
  if (lead.status === 'no_whatsapp_needs_sms') {
    return <WorkSection icon={MessageSquare} iconClass="text-green-500" title="WhatsApp outreach" testId="whatsapp-outreach" summaryClass="text-cyan-600 dark:text-cyan-400"
      summary={`No mobile — landline${lead.line_type && lead.line_type !== 'landline' ? ` (${lead.line_type})` : ''}, flagged, not queued. It can't receive WhatsApp or texts.`} />;
  }
  if (openerReallySent(lead)) {
    return <WorkSection icon={Check} iconClass="text-green-500" title="WhatsApp outreach" testId="whatsapp-outreach"
      summary={`Sent ${sentDay}${lead.whatsapp_template ? ` · ${lead.whatsapp_template}` : ''}${lead.whatsapp_delivery_status ? ` (${lead.whatsapp_delivery_status})` : ''}`} />;
  }
  const summary = queued ? `Queued${lead.whatsapp_template ? ` · ${lead.whatsapp_template}` : ''}` : lead.status === 'whatsapp_failed' ? 'Last send failed' : 'Not queued';
  const dropped = !queued ? queueDropWords(lead.whatsapp_delivery_status) : null;
  const alert = dropped ? (
    <p className="text-[11px] leading-relaxed text-amber-700 dark:text-amber-300" data-testid="queue-drop-reason">{dropped}</p>
  ) : lead.status === 'whatsapp_failed' && !queued ? (
    <p className="text-[11px] leading-relaxed text-amber-700 dark:text-amber-300">Previous WhatsApp send failed (temporary). You can re-queue to try again.</p>
  ) : queued && queueLine.tone === 'paused' ? (
    <p className="text-[11px] font-medium text-amber-700 dark:text-amber-300" data-testid="queued-paused">{queueLine.text}</p>
  ) : null;

  return (
    <WorkSection icon={MessageSquare} iconClass="text-green-500" title="WhatsApp outreach" testId="whatsapp-outreach" summary={summary}
      summaryClass={queued ? 'text-sky-600 dark:text-sky-400' : undefined} alert={alert}>
          <label className="mb-1 block text-[11px] text-muted-foreground">Template</label>
          <Select value={template} disabled={salesPath && queued} onValueChange={(v) => (salesPath ? setSalesTemplate(v) : onUpdate(lead.id, { whatsapp_template: v }))}>
            <SelectTrigger className="h-8 text-xs"><SelectValue placeholder={salesPath && queued ? (lead.whatsapp_template ?? 'Queued') : 'Choose a template'} /></SelectTrigger>
            <SelectContent>
              {options.map((t) => {
                const o = getTemplateSendability(t.value, { shareToken: null }, {});
                return <SelectItem key={t.value} value={t.value} disabled={isInitialOpener(t.value) && !o.ok}>{t.label}{isInitialOpener(t.value) && !o.ok ? ` — ${o.reason}` : ''}</SelectItem>;
              })}
            </SelectContent>
          </Select>
          <p className="mt-1 text-[10px] leading-relaxed text-muted-foreground/60">
            Sends the chosen template with the business name + this lead's claim link.
          </p>
          <TemplateSnippet className="mt-1.5" selected={template} values={{ businessName: lead.business_name, firstName: lead.contact_name, town: lead.derived_town ?? lead.search_location, trade: lead.search_keyword }} />
          <TemplatePreviewButton className="mt-1" selected={template} values={{ businessName: lead.business_name, firstName: lead.contact_name, town: lead.derived_town ?? lead.search_location, trade: lead.search_keyword }} />
          <RequestTemplateButton source="lead" />
          {!(salesPath && queued) && <Button
            size="sm"
            variant={queued ? 'outline' : 'default'}
            className="mt-2.5 h-8 w-full gap-1.5 text-xs"
            onClick={salesPath ? salesQueue : toggleQueue}
            disabled={busy || (!queued && !templateChosen)}
            title={!queued && !templateChosen ? 'Choose a template first' : undefined}
          >
            {busy ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : queued ? <X className="h-3.5 w-3.5" /> : <MessageSquare className="h-3.5 w-3.5" />}
            {queued ? 'Remove from queue' : 'Add to WhatsApp queue'}
          </Button>}
          {/* Says why the button is dead. A disabled control with no explanation reads as a bug,
              and the picker's own placeholder is easy to miss. */}
          {!queued && template && !approval.ok && (
            <p className="mt-1.5 text-center text-[10px] text-amber-700 dark:text-amber-300">{approval.reason}</p>
          )}
          {!queued && !templateChosen && (
            <p className="mt-1.5 text-center text-[10px] text-amber-700 dark:text-amber-300">
              Choose a template above before queueing — nothing is picked by default.
            </p>
          )}
          {queued && (
            <p className={`mt-1.5 text-center text-[10px] ${queueLine.tone === 'paused' ? 'font-medium text-amber-700 dark:text-amber-300' : 'text-sky-600 dark:text-sky-400'}`} data-testid="queued-line">
              {lead.whatsapp_template ? `${lead.whatsapp_template} · ` : ''}{queueLine.text}{salesPath ? ' Ask the admin to take it out of the queue.' : ''}
            </p>
          )}
    </WorkSection>
  );
}
