import { Dialog, DialogContent } from '@/components/ui/dialog';
import { Callout, DialogHero, SubSection } from '@/components/operator/ui';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useToast } from '@/hooks/use-toast';
import { useSubscription } from '@/hooks/useSubscription';
import { useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { isAggregatorUrl } from '@/lib/aggregators';
import { buildFaultLines, type CrawlSignals, type CrawlFault } from '@/lib/crawlCheck';
import type { SiteInfo } from '@/lib/siteInfo';
import { siteInfoHasAnything } from '@/lib/siteInfo';
import type { CrawlRow } from '@/lib/crawlResult';
import type { CrawlRequestSource } from '@/lib/fullCrawl';
import { crawlJobStatus, useCrawlJobWatch } from '@/components/LeadCrawlPanel';
import { ProspectAuditDialog } from '@/components/ProspectAuditDialog';
import { PROSPECT_CRAWL_REUSE_MS } from '@/lib/prospectCrawl';
import { issueWhere, websiteCheckFor, type WebsiteCheckView } from '@/lib/websiteCheck';

/** The minimal lead shape the crawl button/dialog need — an id to crawl by and a website to gate on.
 *  Both the Outreach row (OutreachLead) and the Inbox thread (its lead-lite) satisfy it. */
type CrawlLead = { id: string; website?: string | null };

/* ════════════════════════════════════════════════════════════════════════════════════════════════
   FREE CRAWL CHECK — the button + popup (Paul, 2026-09-16, extended 2026-09-17). Runs the
   `crawl-check` edge function (fetches only, £0 — never the Apify SEO scanner) once and stores the
   result on lead_crawl_checks. ONE code path, three entry points:
     (a) CrawlCheckButton   — on a lead, in the Inbox header AND the Outreach row. Not run → runs it;
         already run → opens the popup on the stored result; no website → disabled.
     (b) CrawlCheckUrlButton — a paste-a-URL box, for a site sent before it's a lead (no storage).

   ⛔ THE POPUP HAS TWO SEPARATE SECTIONS AND THEY MUST NOT LEAK INTO EACH OTHER:
     1. WEBSITE ISSUES — the ONE website check (src/lib/websiteCheck.ts, 2026-10-15): the same stored summary
        the call script, the report and the lead's audit read, so they say the same thing. The button's dot
        reflects ONLY this. (Whether the audit_followup_fault TEMPLATE can be sent is still its own rule,
        buildFaultLines — shown to the admin as a template note, never as the findings.)
     2. SITE INFO — everything else in the same HTML (who built it, directories, contact, …), reading
        material for before a conversation. Its presence NEVER changes the button or the template.

   ⛔ EVERY PRESS STARTS THE EXHAUSTIVE CRAWL JOB (2026-09-23): crawl-check answers at once with a
   job id, the server crawls until the frontier is empty, and this popup only WATCHES the job —
   closing it, or leaving the page, does not stop the crawl.
   ⛔ EVERY PRESS IS THE FULL MANUAL CRAWL (2026-09-23). The button sends `mode: "full"` and the
   screen it sits on (`requested_from`); crawl-check stores the result on the lead's ONE
   lead_crawl_checks row, which Paid Clients and Website Build read too. The automated audit crawl
   never sends `mode` and stays on the small standard profile.
   ════════════════════════════════════════════════════════════════════════════════════════════════ */

interface Verdict { ok: boolean; headline: string; problems: string[] }
interface Result {
  ok: boolean; url?: string; verdict?: Verdict;
  signals?: CrawlSignals; siteInfo?: SiteInfo | null;
  fetches?: number; ms?: number; error?: string; checked_at?: string;
  mode?: 'full' | 'standard'; stored?: boolean | null;
  full?: { completeness?: string; stats?: { pagesFetched?: number; urlsDiscovered?: number; pagesOk?: number; failed?: number; skipped?: number }; warnings?: string[] } | null;
  /** The whole stored result (signals, contentTrust, websiteCheck…) — what the one website check is read from. */
  raw?: Record<string, unknown> | null;
}

/** The ONE website check for what this popup is showing (src/lib/websiteCheck.ts). */
function checkView(result: Result | null, website: string | null | undefined): WebsiteCheckView | null {
  if (!result || !result.ok || !result.signals) return null;
  const raw = (result.raw ?? { url: result.url, signals: result.signals, siteInfo: result.siteInfo, checked_at: result.checked_at }) as never;
  return websiteCheckFor({ result: raw, created_at: result.checked_at ?? null }, { website: website || result.url || null });
}

/** Seed the popup's display state from a stored crawl row (so "already run" shows instantly). */
function resultFromRow(row: CrawlRow | null | undefined): Result | null {
  if (!row?.result?.signals) return null;
  return {
    ok: true, url: row.result.url,
    verdict: row.result.verdict, signals: row.result.signals, siteInfo: row.result.siteInfo ?? null, checked_at: row.result.checked_at ?? row.created_at,
    raw: row.result as unknown as Record<string, unknown>,
  };
}

function CopyIcon({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const { toast } = useToast();
  return (
    <button
      type="button"
      onClick={async () => {
        try { await navigator.clipboard.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 1500); }
        catch { toast({ title: 'Copy failed', variant: 'destructive' }); }
      }}
      className="mt-0.5 shrink-0 text-muted-foreground hover:text-foreground"
      title="Copy this line"
    >
      {copied ? <Check className="h-3.5 w-3.5 text-green-500" /> : <Copy className="h-3.5 w-3.5" />}
    </button>
  );
}

/* ── SITE INFO rendering ────────────────────────────────────────────────────────────────────────── */

function InfoRow({ label, children, missing }: { label: string; children?: ReactNode; missing?: boolean }) {
  return (
    <div className="flex gap-2 py-1 text-sm">
      <span className="w-28 shrink-0 text-muted-foreground">{label}</span>
      <span className={missing ? 'text-muted-foreground/50 italic' : 'flex-1 break-words'}>
        {missing ? 'Not found' : children}
      </span>
    </div>
  );
}

function SiteInfoView({ info }: { info: SiteInfo | null | undefined }) {
  if (!info) {
    return <p className="text-sm text-muted-foreground/70 italic">Site info wasn&rsquo;t captured on this check — run again to read it.</p>;
  }
  if (!siteInfoHasAnything(info)) {
    return <p className="text-sm text-muted-foreground/70 italic">Nothing readable found on the page.</p>;
  }
  const built = info.builtBy;
  const builtMissing = !built.credit && !built.platform && built.footerLinks.length === 0;
  return (
    <div className="divide-y divide-border/50">
      {/* The two Paul reads first. */}
      <InfoRow label="Who built it" missing={builtMissing}>
        {!builtMissing && (
          <span className="space-y-0.5">
            {built.credit && <span className="block">{built.credit}</span>}
            {built.platform && <span className="block text-muted-foreground">Platform: {built.platform}</span>}
            {built.footerLinks.length > 0 && (
              <span className="block text-muted-foreground">Footer links: {built.footerLinks.join(', ')}</span>
            )}
          </span>
        )}
      </InfoRow>
      <InfoRow label="Directories" missing={info.directories.length === 0}>
        {info.directories.length > 0 && (
          <span className="flex flex-wrap gap-1">
            {info.directories.map((d) => (
              <span key={d} className={`rounded-full px-2 py-0.5 text-xs ${d === 'Yell' ? 'bg-amber-500/15 text-amber-700 dark:text-amber-400 font-semibold' : 'bg-muted text-foreground/80'}`}>{d}</span>
            ))}
          </span>
        )}
      </InfoRow>

      <InfoRow label="Email" missing={!info.email}>{info.email}</InfoRow>
      <InfoRow label="Phone" missing={!info.phone}>{info.phone}</InfoRow>
      <InfoRow label="Address" missing={!info.address}>{info.address}</InfoRow>
      <InfoRow label="Opening hours" missing={!info.openingHours?.length}>
        {info.openingHours?.join(' · ')}
      </InfoRow>
      <InfoRow label="Company no." missing={!info.companyNumber}>{info.companyNumber}</InfoRow>
      <InfoRow label="Social" missing={info.socialLinks.length === 0}>
        {info.socialLinks.length > 0 && (
          <span className="flex flex-wrap gap-x-2 gap-y-0.5">
            {info.socialLinks.map((s) => (
              <a key={s.platform} href={s.url} target="_blank" rel="noreferrer" className="text-primary hover:underline">{s.platform}</a>
            ))}
          </span>
        )}
      </InfoRow>
      <InfoRow label="Services" missing={info.services.length === 0}>
        {info.services.length > 0 && info.services.join(', ')}
      </InfoRow>
      <InfoRow label="Towns" missing={info.towns.length === 0}>
        {info.towns.length > 0 && info.towns.join(', ')}
      </InfoRow>
      <InfoRow label="Copyright yr" missing={!info.staleness.copyrightYear}>{info.staleness.copyrightYear}</InfoRow>
      <InfoRow label="Latest date" missing={!info.staleness.lastDatePublished}>{info.staleness.lastDatePublished}</InfoRow>
    </div>
  );
}

/* ── the dialog ─────────────────────────────────────────────────────────────────────────────────── */

function CrawlCheckDialog(
  { open, onOpenChange, lead, initialCrawl, urlMode, from, onDone, onRunningChange, onErrorChange }:
  { open: boolean; onOpenChange: (o: boolean) => void; lead?: CrawlLead; initialCrawl?: CrawlRow | null; urlMode?: boolean; from: CrawlRequestSource; onDone?: () => void; onRunningChange?: (running: boolean) => void; onErrorChange?: (failed: boolean) => void },
) {
  const { toast } = useToast();
  /* Sales sees the findings and the site info; the template-routing note is operator workflow. */
  const isAdmin = useSubscription().role === 'admin';
  const queryClient = useQueryClient();
  const [running, setRunning] = useState(false);
  const [result, setResult] = useState<Result | null>(null);
  const [url, setUrl] = useState('');
  const [jobId, setJobId] = useState<string | null>(null);
  /* A press inside the reuse window opens the SAVED crawl (prospectCrawl.ts) — said, never passed off as new. */
  const [savedAt, setSavedAt] = useState<string | null>(null);
  const [fullOpen, setFullOpen] = useState(false);
  const job = useCrawlJobWatch(open ? jobId : null, async () => {
    if (!jobId) return;
    try {
      const res = await crawlJobStatus({ job_id: jobId, include_result: true });
      const r = res.result as Record<string, any> | null;
      if (!r?.signals) throw new Error(res.job?.status === 'failed' ? 'The crawl failed.' : 'The crawl finished without a readable result.');
      setResult({ ok: true, url: r.url, verdict: r.verdict, signals: r.signals, siteInfo: r.siteInfo ?? null, checked_at: r.checked_at, full: res.full ?? null, mode: 'full', raw: r });
      void queryClient.invalidateQueries({ queryKey: ['lead-crawls'] });
      void queryClient.invalidateQueries({ queryKey: ['inbox'] });
      void queryClient.invalidateQueries({ queryKey: ['cold-call-playbook'] });   // the call script reads this crawl too
      onDone?.();
    } catch (e) {
      setResult({ ok: false, error: e instanceof Error ? e.message : 'crawl failed' });
      onErrorChange?.(true);
    } finally {
      setJobId(null); setRunning(false); onRunningChange?.(false);
    }
  });

  const run = async (body: { lead_id?: string; url?: string; town?: string }) => {
    setRunning(true); onRunningChange?.(true); setResult(null); onErrorChange?.(false); setSavedAt(null);
    try {
      const { data, error } = await supabase.functions.invoke('crawl-check', { body: { ...body, mode: 'full', requested_from: from } });
      if (error) throw new Error(error.message);
      const next = data as Result;
      if (!next?.ok) throw new Error(next?.error || 'check failed');
      if ((next as { cached?: boolean }).cached) setSavedAt(String((next as { crawled_at?: string }).crawled_at ?? '') || null);
      if ((next as { job_id?: string }).job_id) {
        // The exhaustive job is running on the server; the watcher above finishes the popup.
        setJobId(String((next as { job_id?: string }).job_id));
        return;
      }
      if (body.lead_id && next.stored === false) throw new Error('The crawl ran but could not be saved to this lead. Run it again.');
      setResult({ ...next, raw: next as unknown as Record<string, unknown> });
      if (body.lead_id) {
        // The ONE crawl row changed: every screen's copy (Outreach, Paid Clients, lead popup) re-reads.
        void queryClient.invalidateQueries({ queryKey: ['lead-crawls'] });
        // Inbox intentionally has a five-minute cache; invalidate it so returning to a
        // conversation immediately re-reads this manual crawl for audit_followup_fault.
        void queryClient.invalidateQueries({ queryKey: ['inbox'] });
        // The call script reads this crawl too: without this it kept "Website not checked yet" from before the run.
        void queryClient.invalidateQueries({ queryKey: ['cold-call-playbook'] });
      }
      if (body.lead_id) onDone?.();     // stored → let the parent refresh the button state
    } catch (e) {
      setResult({ ok: false, error: e instanceof Error ? e.message : 'check failed' });
      onErrorChange?.(true);
      setRunning(false);
      onRunningChange?.(false);
    }
  };
  /* A job-less answer (the inline check) is finished the moment it returns. */
  useEffect(() => { if (result && !jobId) { setRunning(false); onRunningChange?.(false); } /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [result, jobId]);

  /* On open: show the STORED result if there is one (already run → open the popup), otherwise run it
     (not run yet → run the crawl). Reset when closed. */
  useEffect(() => {
    if (!open) { setResult(null); setUrl(''); setRunning(false); setJobId(null); return; }
    if (urlMode) return;
    const stored = resultFromRow(initialCrawl);
    if (stored) setResult(stored);
    else if (lead && !running) void run({ lead_id: lead.id });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  /* The audit_followup_fault TEMPLATE's own rule (admin note only) — never the findings shown. */
  const faults: CrawlFault[] = result?.signals ? buildFaultLines(result.signals) : [];
  const fetchFailed = result?.signals?.fetchFailed === true;
  const view = checkView(result, lead?.website);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg max-h-[85vh] overflow-y-auto">
        <DialogHero
          icon={ScanSearch}
          tone="blue"
          title="Crawl check"
          subtitle="free · what AI sees"
          chips={lead && !urlMode ? (
            <>
              <Button size="sm" variant="outline" className="h-7 text-xs" disabled={running}
                onClick={() => void run({ lead_id: lead.id })}>
                {running ? <Loader2 className="mr-1 h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="mr-1 h-3.5 w-3.5" />}
                Run again
              </Button>
              <Button size="sm" variant="outline" className="h-7 text-xs" onClick={() => setFullOpen(true)} data-testid="crawl-open-full-audit">
                Full audit
              </Button>
            </>
          ) : undefined}
        />
        {lead && !urlMode && <ProspectAuditDialog leadId={lead.id} open={fullOpen} onOpenChange={setFullOpen} />}
        {savedAt && <p className="-mt-2 text-xs text-muted-foreground" data-testid="crawl-saved-note">Saved crawl from {new Date(savedAt).toLocaleString('en-GB')} reused — this site was crawled within the last {Math.round(PROSPECT_CRAWL_REUSE_MS / 86_400_000)} days, so it was not crawled again.</p>}

        {urlMode && (
          <form onSubmit={(e) => { e.preventDefault(); if (url.trim()) void run({ url: url.trim() }); }} className="flex gap-2">
            <Input placeholder="example.co.uk" value={url} onChange={(e) => setUrl(e.target.value)} autoFocus />
            <Button type="submit" disabled={running || !url.trim()}>
              {running ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Check'}
            </Button>
          </form>
        )}

        {running && (
          <div className="flex items-center gap-2 py-6 text-sm text-muted-foreground">
            <Loader2 className="h-4 w-4 animate-spin" /> {job?.label || 'Starting the full crawl…'} — it runs on the server until every page is done; you can close this.
          </div>
        )}

        {result && !running && (
          <div className="space-y-5">
            {result.error && <Callout tone="red" icon={AlertTriangle}>{result.error}</Callout>}

            {result.signals && (
              <div className="rounded-xl bg-muted/40 px-3 py-2 text-xs text-muted-foreground ring-1 ring-inset ring-border/40">
                <span className="font-medium text-foreground">{fetchFailed ? 'Could not read website' : 'Crawl complete'}</span>
                {result.full?.stats ? ` · full crawl · ${(result.full.stats.urlsDiscovered ?? 0).toLocaleString('en-GB')} discovered · ${(result.full.stats.pagesOk ?? 0).toLocaleString('en-GB')} fetched · ${result.full.stats.failed ?? 0} failed · ${result.full.stats.skipped ?? 0} skipped${result.full.completeness === 'complete_with_failures' ? ' (complete with failures)' : ''}` : result.signals.pagesChecked != null && ` · ${result.signals.pagesChecked} pages checked`}
                {result.checked_at && ` · ${new Date(result.checked_at).toLocaleString()}`}
              </div>
            )}

            {/* ── SECTION 1: WEBSITE ISSUES — the ONE website check (src/lib/websiteCheck.ts) ── */}
            {result.signals && view && (
              <SubSection title="Website issues" icon={AlertTriangle} tone="amber" className="space-y-2">
                <p className={`flex items-center gap-1.5 text-sm ${view.state === 'clean' ? 'text-teal-700 dark:text-teal-300' : view.state === 'issues' ? 'font-medium' : 'text-muted-foreground'}`} data-testid="crawl-website-headline">
                  {view.state === 'clean' && <CircleCheck className="h-4 w-4" />}{view.headline}
                </p>
                {view.coverageLine && <p className="text-[11px] text-muted-foreground" data-testid="crawl-website-coverage">{view.coverageLine}</p>}
                {view.serious.length > 0 && (
                  <>
                  {/* The one sentence Sales may say about any of these (Paul, 2026-09-28): they MAY make
                      it harder — never "this is why AI did not recommend you". */}
                  <p className="text-xs text-muted-foreground" data-testid="crawl-careful-wording">
                    These may make it harder for search engines or AI systems to crawl, understand or verify the business.
                  </p>
                  <ul className="space-y-2" data-testid="crawl-website-issues">
                    {view.serious.map((f) => (
                      <li key={f.id} className="flex items-start gap-2 text-sm">
                        <span className={`mt-1 h-1.5 w-1.5 shrink-0 rounded-full ${f.severity === 'high' ? 'bg-red-500' : 'bg-amber-500'}`} />
                        <span className="flex-1">
                          <span className="font-medium">{f.title}. </span>
                          <span className="text-muted-foreground">{f.saw}</span>
                          {issueWhere(f) && <span className="block break-all text-[11px] text-muted-foreground/80">{issueWhere(f)}</span>}
                        </span>
                        <CopyIcon text={f.title + '. ' + f.saw} />
                      </li>
                    ))}
                  </ul>
                  </>
                )}
                {view.minor.length > 0 && (
                  <details className="text-xs text-muted-foreground" data-testid="crawl-website-minor">
                    <summary className="cursor-pointer">{view.minor.length} minor {view.minor.length === 1 ? 'point' : 'points'}</summary>
                    <ul className="mt-1 list-disc space-y-0.5 pl-5">{view.minor.map((f) => <li key={f.id}>{f.title} — {f.saw}</li>)}</ul>
                  </details>
                )}
              </SubSection>
            )}

            {/* ── SECTION 2: SITE INFO (reading material — never gates a template) ── */}
            {isAdmin && result.signals && !fetchFailed && (
              <p className={`text-xs ${faults.length ? 'text-teal-700 dark:text-teal-300' : 'text-muted-foreground'}`}>
                {faults.length
                  ? 'WhatsApp template audit_followup_fault: usable — it names "' + faults[0].title + '".'
                  : 'WhatsApp template audit_followup_fault: not usable — it only names crawler, JavaScript, duplicate-page and thin-page faults, and none were found.'}
              </p>
            )}

            {!urlMode && (
              <SubSection title="Site info" tone="blue" className="space-y-2">
                <SiteInfoView info={result.siteInfo} />
              </SubSection>
            )}

            {result.signals?.checkedPages && result.signals.checkedPages.length > 0 && (
              <SubSection title="Pages checked" tone="grey" className="space-y-2">
                <ul className="space-y-1 text-xs">
                  {result.signals.checkedPages.map((page) => (
                    <li key={page.url} className="flex items-start justify-between gap-3 rounded-lg border border-border/50 px-2 py-1.5">
                      <a href={page.url} target="_blank" rel="noreferrer" className="min-w-0 truncate text-primary hover:underline">{page.url}</a>
                      <span className="shrink-0 text-muted-foreground">{page.kind} · {page.readable ? page.words + ' words' : 'unreadable'}</span>
                    </li>
                  ))}
                </ul>
              </SubSection>
            )}

            <p className="text-[11px] text-muted-foreground">
              {result.url}{result.fetches != null ? ` · ${result.fetches} fetches` : ''}{result.ms != null ? ` · ${(result.ms / 1000).toFixed(1)}s` : ''}
            </p>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

/* ── (a) the per-lead button — Inbox header + Outreach row ──────────────────────────────────────── */

/** Crawl-site button for a lead. `crawl` is that lead's newest stored crawl row (from the caller's
 *  map), or null/undefined when it hasn't been run. The dot reflects ONLY an AI-visibility fault.
 *  `onDone` refetches the caller's crawl data after a run so the button restyles. */
export function CrawlCheckButton(
  { lead, crawl, onDone, className, iconOnly = false, from }:
  { lead: CrawlLead; crawl?: CrawlRow | null; onDone?: () => void; className?: string; iconOnly?: boolean; from: CrawlRequestSource },
) {
  const [open, setOpen] = useState(false);
  const [running, setRunning] = useState(false);
  const [failed, setFailed] = useState(false);
  const hasRealSite = !!lead.website?.trim() && !isAggregatorUrl(lead.website);
  const ran = !!crawl?.result?.signals;
  const crawlFailed = crawl?.result?.signals?.fetchFailed === true;
  /* The dot reflects the ONE website check — the same answer the popup, the call script and the report give. */
  const view = ran ? websiteCheckFor({ result: crawl!.result as never, created_at: crawl!.created_at ?? null }, { website: lead.website }) : null;
  const faulted = view?.state === 'issues';

  const base = 'inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors';
  const iconBase = 'inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-40';

  if (!hasRealSite) {
    if (iconOnly) {
      return (
        <button type="button" disabled title="No website to crawl." aria-label="No website to crawl."
          className={`${iconBase} cursor-not-allowed ${className ?? ''}`}>
          <ScanSearch className="h-4 w-4" />
        </button>
      );
    }
    return (
      <button type="button" disabled title="No website to crawl."
        className={`${base} cursor-not-allowed border-border/50 bg-muted/40 text-muted-foreground/50 ${className ?? ''}`}>
        <ScanSearch className="h-3 w-3" /> Crawl site
      </button>
    );
  }

  const tone = !ran
    ? 'border-primary/30 bg-primary/10 text-primary hover:bg-primary/20'
    : faulted
      ? 'border-red-500/40 bg-red-500/10 text-red-600 dark:text-red-400 hover:bg-red-500/20'
      : 'border-emerald-500/40 bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 hover:bg-emerald-500/20';
  if (iconOnly) {
    const iconTitle = running ? 'Crawling website…' : failed || crawlFailed ? 'Crawl failed — click to retry' : ran ? (view?.headline ?? 'View crawl result') : 'Crawl website';
    return (
      <>
        <button type="button" onClick={() => setOpen(true)} disabled={running} title={iconTitle} aria-label={iconTitle}
          className={`${iconBase} ${failed || crawlFailed ? 'text-destructive hover:text-destructive' : faulted ? 'text-red-500 hover:text-red-500' : ran ? 'text-emerald-600 hover:text-emerald-600 dark:text-emerald-400' : ''} ${className ?? ''}`}>
          {running ? <ScanSearch className="h-4 w-4 animate-spin" /> : failed || crawlFailed ? <AlertTriangle className="h-4 w-4" /> : <ScanSearch className="h-4 w-4" />}
        </button>
        <CrawlCheckDialog open={open} onOpenChange={setOpen} lead={lead} initialCrawl={crawl} from={from} onDone={onDone} onRunningChange={setRunning} onErrorChange={setFailed} />
      </>
    );
  }

  const title = !ran
    ? 'Not checked yet — click to crawl the site (free)'
    : `${view?.headline ?? 'Checked.'} Click to view.`;

  return (
    <>
      <button type="button" onClick={() => setOpen(true)} title={title} className={`${base} ${tone} ${className ?? ''}`}>
        <ScanSearch className="h-3 w-3" /> Crawl site
        {ran && (faulted
          ? <span className="ml-0.5 h-1.5 w-1.5 rounded-full bg-red-500" />
          : <CircleCheck className="ml-0.5 h-3 w-3" />)}
      </button>
      <CrawlCheckDialog open={open} onOpenChange={setOpen} lead={lead} initialCrawl={crawl} from={from} onDone={onDone} onRunningChange={setRunning} onErrorChange={setFailed} />
    </>
  );
}

/* ── (b) paste a URL — for a site sent before it's a lead ───────────────────────────────────────── */

export function CrawlCheckUrlButton() {
  const [open, setOpen] = useState(false);
  return (
    <>
      <Button variant="outline" size="sm" onClick={() => setOpen(true)}>
        <ScanSearch className="mr-1.5 h-3.5 w-3.5" /> Crawl check
      </Button>
      <CrawlCheckDialog open={open} onOpenChange={setOpen} urlMode from="outreach" />
    </>
  );
}
