const defaultConfig = {
  label: 'New',
  shortLabel: 'New',
  className: 'bg-[hsl(var(--badge-new))] text-[hsl(var(--badge-new-fg))] border-transparent font-semibold',
};

/** The words this badge shows for a status — the Outreach row compares them with the sales-state pill so
 *  the same state is never drawn twice (leadState.stateShownByBadge). */
export function pipelineStatusLabel(status: string | null | undefined): string {
  if (!status) return defaultConfig.label;
  return statusConfig[status]?.label ?? String(status).replace(/_/g, ' ');
}

export function PipelineStatusBadge({ status, compact }: PipelineStatusBadgeProps) {
  /* No status → New. A status this map does not know shows AS ITSELF, never as "New" — an unknown value
     read as the empty one is the absent-falls-through trap. */
  const unknown = status && !statusConfig[status]
    ? { label: String(status).replace(/_/g, ' '), shortLabel: String(status).replace(/_/g, ' '), className: 'bg-muted text-foreground border-transparent font-semibold' }
    : null;
  const config = status ? (statusConfig[status] ?? unknown ?? defaultConfig) : defaultConfig;
  const isInterested = status === 'interested';

  return (
    <Badge
      variant="outline"
      className={`${config.className} ${compact ? 'text-[10px] px-1.5 py-0 rounded-md' : ''} ${isInterested ? 'gap-1' : ''}`}
    >
      {isInterested && (
        <Star className={`${compact ? 'h-2.5 w-2.5' : 'h-3 w-3'} text-[hsl(var(--badge-interested-fg))] fill-[hsl(var(--badge-interested-fg))]`} />
      )}
      {compact ? config.shortLabel : config.label}
    </Badge>
  );
}
